import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

public class RecurringEventPlannerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Set<LocalDate> none() {
        return new HashSet<>();
    }

    static Set<LocalDate> cancel(String... dates) {
        Set<LocalDate> out = new HashSet<>();
        for (String date : dates) {
            out.add(LocalDate.parse(date));
        }
        return out;
    }

    static Object plan(LocalDate start, DayOfWeek day, int everyNWeeks, int count, Set<LocalDate> cancelled) {
        try {
            List<LocalDate> dates = RecurringEventPlanner.occurrences(start, day, everyNWeeks, count, cancelled);
            return dates == null ? "<null>" : dates.toString();
        } catch (Throwable crash) {
            return "occurrences threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        LocalDate newYear = LocalDate.of(2024, 1, 1);

        check("every other Wednesday", "[2024-01-03, 2024-01-17, 2024-01-31]",
                plan(newYear, DayOfWeek.WEDNESDAY, 2, 3, none()));
        check("a cancellation does not shift the schedule",
                "[2024-01-03, 2024-01-31, 2024-02-14]",
                plan(newYear, DayOfWeek.WEDNESDAY, 2, 3, cancel("2024-01-17")));
        check("start already falls on the chosen day",
                "[2024-01-01, 2024-01-08, 2024-01-15]",
                plan(newYear, DayOfWeek.MONDAY, 1, 3, none()));
        check("a weekly series crossing a month end",
                "[2024-01-26, 2024-02-02, 2024-02-09]",
                plan(LocalDate.of(2024, 1, 22), DayOfWeek.FRIDAY, 1, 3, none()));
        check("two cancellations in a row",
                "[2024-01-01, 2024-01-22]",
                plan(newYear, DayOfWeek.MONDAY, 1, 2, cancel("2024-01-08", "2024-01-15")));
        check("a count of zero", "[]", plan(newYear, DayOfWeek.MONDAY, 1, 0, none()));
        check("a step of zero weeks", "[]", plan(newYear, DayOfWeek.MONDAY, 0, 3, none()));
        check("a monthly-ish four week rhythm",
                "[2024-01-04, 2024-02-01, 2024-02-29]",
                plan(newYear, DayOfWeek.THURSDAY, 4, 3, none()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

