/**
 * TASK: Generate the dates of a recurring meeting.
 *
 * occurrences(start, dayOfWeek, everyNWeeks, count, cancelled):
 *   - the first candidate is the first date on or after start whose day of week
 *     is dayOfWeek (start itself counts if it already falls on that day),
 *   - each following candidate is everyNWeeks * 7 days after the previous one,
 *   - a candidate that appears in the cancelled set is skipped but the schedule
 *     is NOT shifted: the next candidate is still everyNWeeks later,
 *   - collecting stops once count dates have been kept, or after 500 candidates
 *     have been examined, whichever happens first,
 *   - count of 0 or less, or everyNWeeks of 0 or less, gives an empty list.
 *
 * Example: start 2024-01-01 (a Monday), WEDNESDAY, every 2 weeks, 3 dates,
 *          nothing cancelled -> [2024-01-03, 2024-01-17, 2024-01-31]
 *          With 2024-01-17 cancelled -> [2024-01-03, 2024-01-31, 2024-02-14]
 */
import java.time.DayOfWeek;
import java.time.LocalDate;
import java.util.ArrayList;
import java.util.List;
import java.util.Set;

public class RecurringEventPlanner {

    public static List<LocalDate> occurrences(LocalDate start, DayOfWeek dayOfWeek,
                                              int everyNWeeks, int count, Set<LocalDate> cancelled) {
        List<LocalDate> dates = new ArrayList<>();
        if (count <= 0 || everyNWeeks <= 0) {
            return dates;
        }
        LocalDate candidate = start;
        while (candidate.getDayOfWeek() != dayOfWeek) {
            candidate = candidate.plusDays(1);
        }
        int examined = 0;
        while (dates.size() < count && examined < 500) {
            examined++;
            if (cancelled == null || !cancelled.contains(candidate)) {
                dates.add(candidate);
            }
            candidate = candidate.plusWeeks(everyNWeeks);
        }
        return dates;
    }
}
